def create_profiles(apps, schema_editor):
    """Every existing user gets a lifecycle profile (stable anonymous ref, reminders on, do_not_contact off).

    Only creates rows: no email is reserved or sent by this migration."""
    User = apps.get_model("auth", "User")
    Profile = apps.get_model("gemiapp", "UserLifecycleProfile")
    existing = set(Profile.objects.values_list("user_id", flat=True))
    Profile.objects.bulk_create(
        [Profile(user_id=pk, ref=uuid.uuid4()) for pk in User.objects.values_list("pk", flat=True) if pk not in existing],
        batch_size=500,
    )


